#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto apply=[&](int x,int y){
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };
    for(int i=0;i<n-1;i++){
        int j=-1;
        for(int k=i;k<n;k++) if(p[k]==i+1){j=k;break;}
        if(j==i) continue;
        int rem=n-i; // working with positions i..n-1
        // Bring p[j] to position i
        // Step 1: bring to last position (n-1)
        if(j!=n-1){
            // x=j+1, y=n-1-j => x+y=n, invalid
            // x=j, y=n-1-j: suffix=p[j+1..n-1], mid=p[j], prefix=p[0..j-1]
            // p[j] at pos n-1-j. 
            // x=1, y=n-1-j: suffix=p[j+1..n-1], mid=p[1..j], prefix=p[0]
            // p[j] at pos n-1-j+j-1 = n-2. Close to end but not end.
            // To get p[j] to end: need it in prefix. x=j+1,y=1 if j+2<n
            if(j+2<=n-1){
                apply(j+1,1);
                // p[j] was in prefix (pos j), goes to end at pos n-(j+1)+j = n-1. But prefix goes to END.
                // new: [p[n-1]], [p[j+1..n-2]], [p[0..j]]. p[j] at pos n-1. Good!
            } else {
                // j+2>n-1 means j>=n-2, j=n-2
                apply(1,1);
                // find again
                for(int k=i;k<n;k++) if(p[k]==i+1){j=k;break;}
                if(j==i) continue;
                if(j!=n-1 && j+2<=n-1){ apply(j+1,1); }
                else if(j==n-1){/* already at end */}
            }
            j=n-1;
        }
        // Now target at position n-1. Bring to position i.
        // x=i, y=n-1-i: suffix=p[i+1..n-1] includes p[n-1], mid=p[i], prefix=p[0..i-1]
        // Result: [p[i+1..n-1],p[i],p[0..i-1]]. target at pos n-1-i-1=n-i-2? No: suffix len=n-1-i, target is last of suffix -> pos n-1-i-1. Nah pos n-2-i. Hmm not i.
        // x=n-1-i,y=1: [p[n-1]],[p[n-1-i..n-2]],[p[0..n-2-i]]. target at pos 0! Then need to move to i.
        if(i==0) { apply(n-1,1); /* target goes to pos 0 */ }
        else { apply(n-1-i,1); apply(1,n-1-i); }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
